import java.io.*;
import java.util.*;

public class Main {
    static class Node {
        int value;
        int priority;
        int index;

        Node(int value, int priority, int index) {
            this.value = value;
            this.priority = priority;
            this.index = index;
        }
    }

    static class PriorityQueue {
        private List<Node> heap = new ArrayList<>();
        private int indexCounter = 0;

        public void enqueue(int value, int priority) {
            Node node = new Node(value, priority, indexCounter++);
            heap.add(node);
            int i = heap.size() - 1;
            bubbleUp(i);
        }

        public int peek() {
            if (heap.isEmpty()) return -1;
            return heap.get(0).value;
        }

        public int dequeue() {
            if (heap.isEmpty()) return -1;
            Node result = heap.get(0);
            Node last = heap.remove(heap.size() - 1);
            if (!heap.isEmpty()) {
                heap.set(0, last);
                heapify(0);
            }
            return result.value;
        }

        private void bubbleUp(int i) {
            while (i > 0) {
                int parent = (i - 1) / 2;
                if (compare(heap.get(i), heap.get(parent)) > 0) {
                    Collections.swap(heap, i, parent);
                    i = parent;
                } else {
                    break;
                }
            }
        }

        private void heapify(int i) {
            int largest = i;
            int left = 2 * i + 1;
            int right = 2 * i + 2;

            if (left < heap.size() && compare(heap.get(left), heap.get(largest)) > 0) {
                largest = left;
            }
            if (right < heap.size() && compare(heap.get(right), heap.get(largest)) > 0) {
                largest = right;
            }

            if (largest != i) {
                Collections.swap(heap, i, largest);
                heapify(largest);
            }
        }

        private int compare(Node a, Node b) {
            if (a.priority != b.priority) {
                return Integer.compare(a.priority, b.priority);
            }
            return Integer.compare(a.index, b.index);
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PriorityQueue pq = new PriorityQueue();

        int n = Integer.parseInt(br.readLine().trim());

        for (int i = 0; i < n; i++) {
            String line = br.readLine().trim();
            String[] parts = line.split("\\s+");

            if (parts[0].equals("ENQUEUE")) {
                int value = Integer.parseInt(parts[1]);
                int priority = Integer.parseInt(parts[2]);
                pq.enqueue(value, priority);
            } else if (parts[0].equals("DEQUEUE")) {
                System.out.println(pq.dequeue());
            } else if (parts[0].equals("PEEK")) {
                System.out.println(pq.peek());
            }
        }
    }
}
